import { Combobox } from '@refy-design/web';
import type { ComboboxOption } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const projects: ComboboxOption[] = [
  {
    value: 'aurora',
    label: 'aurora.example.com',
    lead: 'RS',
    meta: '12 tasks',
    group: 'Suggestions',
  },
  {
    value: 'horizonte',
    label: 'horizonte.example.com',
    lead: 'RS',
    meta: '8 tasks',
    group: 'Suggestions',
  },
  {
    value: 'origin',
    label: 'origem.example.com',
    lead: 'RR',
    meta: '5 tasks',
    group: 'Suggestions',
  },
  {
    value: 'atlas',
    label: 'atlas.example.com',
    lead: 'RD',
    meta: '4 tasks',
    group: 'Suggestions',
  },
  {
    value: 'north',
    label: 'north.example.com',
    lead: 'RB',
    meta: '6 tasks',
    group: 'Suggestions',
  },
];
export function Example() {
  const args: Pick<ComponentProps<typeof Combobox>, 'label' | 'options'> = {
    label: 'Project',
    options: projects,
  };
  const [selected, setSelected] = useState<string | null>(null);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <Combobox
        {...args}
        value={selected}
        onChange={(option) => setSelected(option?.value ?? null)}
      />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-3)' }}
      >
        selected: {selected ?? '—'}
      </code>
    </div>
  );
}

